def get_error_message(key: str, language: str = "en", **kwargs: Any) -> str:
    """Get a localized error message by key.

    Falls back to English if the key is not found in the requested language.
    Supports interpolation with {{key}} syntax.
    """
    locale = ERROR_MESSAGES.get(language, ERROR_MESSAGES["en"])
    template = locale.get(key, ERROR_MESSAGES["en"].get(key, key))

    if kwargs:
        for k, v in kwargs.items():
            template = template.replace(f"{{{k}}}", str(v))

    return template


def get_status_message(key: str, language: str = "en", **kwargs: Any) -> str:
    """Get a localized status message by key.

    Falls back to English if the key is not found in the requested language.
    """
    locale = STATUS_MESSAGES.get(language, STATUS_MESSAGES["en"])
    template = locale.get(key, STATUS_MESSAGES["en"].get(key, key))

    if kwargs:
        for k, v in kwargs.items():
            template = template.replace(f"{{{k}}}", str(v))

    return template
